Here is the root cause:
Using devm_request_irq() before devm_power_supply_register() causes devm resources to be freed in reverse order, so the power_supply handle is freed before the IRQ handler is unregistered. This creates a race condition where an interrupt can fire after the power_supply is freed, leading to use-after-free in power_supply_changed(). Additionally, during probe, an interrupt could fire before the power_supply is registered, causing use of an uninitialized pointer.

Here is the patch:

 static int act8945a_charger_probe(struct platform_device *pdev)
 {
 	struct act8945a_charger *charger;
 	struct power_supply_config psy_cfg = {};
 	int irq, ret;

 	charger = devm_kzalloc(&pdev->dev, sizeof(*charger), GFP_KERNEL);
 	if (!charger)
 		return -ENOMEM;

 	charger->regmap = dev_get_regmap(pdev->dev.parent, NULL);
 	if (!charger->regmap) {
 		dev_err(&pdev->dev, "Parent did not provide regmap\n");
 		return -EINVAL;
 	}

 	ret = act8945a_charger_config(&pdev->dev, charger);
 	if (ret)
 		return ret;

 	irq = of_irq_get(pdev->dev.of_node, 0);
 	if (irq <= 0) {
 		dev_err(&pdev->dev, "failed to find IRQ number\n");
 		return irq ?: -ENXIO;
 	}

-	ret = devm_request_irq(&pdev->dev, irq, act8945a_status_changed,
-			       IRQF_TRIGGER_FALLING, "act8945a_interrupt",
-			       charger);
-	if (ret) {
-		dev_err(&pdev->dev, "failed to request nIRQ pin IRQ\n");
-		return ret;
-	}
-
 	charger->desc.name = "act8945a-charger";
 	charger->desc.get_property = act8945a_charger_get_property;
 	charger->desc.properties = act8945a_charger_props;
 	charger->desc.num_properties = ARRAY_SIZE(act8945a_charger_props);

 	ret = act8945a_set_supply_type(charger, &charger->desc.type);
 	if (ret)
 		return -EINVAL;

 	psy_cfg.fwnode	= dev_fwnode(&pdev->dev);
 	psy_cfg.drv_data = charger;

 	charger->psy = devm_power_supply_register(&pdev->dev,
 						  &charger->desc,
 						  &psy_cfg);
 	if (IS_ERR(charger->psy)) {
 		dev_err(&pdev->dev, "failed to register power supply\n");
 		return PTR_ERR(charger->psy);
 	}

+	ret = devm_request_irq(&pdev->dev, irq, act8945a_status_changed,
+			       IRQF_TRIGGER_FALLING, "act8945a_interrupt",
+			       charger);
+	if (ret) {
+		dev_err(&pdev->dev, "failed to request nIRQ pin IRQ\n");
+		return ret;
+	}
+
 	platform_set_drvdata(pdev, charger);

 	INIT_WORK(&charger->work, act8945a_work);

 	ret = act8945a_enable_interrupt(charger);
 	if (ret)
 		return -EIO;

 	charger->init_done = true;

 	return 0;
 }



